entries[210689] = { ["name"] = "Blitzableiter", ["text"] = "Verstärkung ( Verstärkungsschamane )\n'Blitzschlag', 'Elementarschlag', 'Urzeitliche Welle' und 'Kettenblitzschlag' lassen Euer Ziel für 8 Sek. zu einem Blitzableiter werden.\n\nBlitzableiter erleiden 10% jeglichen Schadens, den Ihr mit 'Blitzschlag' und 'Kettenblitzschlag' verursacht.\n\nElementar\n[ Sturmgewitter : 'Sturmgewitter' ] [ Elementar : 'Erdschock', 'Elementarschlag' und 'Erdbeben' / 'Blitzschlag', 'Elementarschlag', 'Urzeitliche Welle' und 'Kettenblitzschlag' ] lassen Euer Ziel für 8 Sek. zu einem Blitzableiter werden.\n\nBlitzableiter erleiden 10% jeglichen Schadens, den Ihr mit [ Sturmgewitter : 'Sturmgewitter', Blitzschlag' / 'Blitzschlag'] und 'Kettenblitzschlag' verursacht." }
