entries[210863] = { ["name"] = "Windende Schatten", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Boss ruft Schattentornados hervor, die sich bei zufälligen Gegnern bilden. Nach 10 Sek. erscheinen die Tornados an den Gegnerpositionen, ziehen Ziele in der Nähe 4 Sek. lang zu sich heran und fügen ihnen so alle 1 Sek. 2134 Schattenschaden zu.\n\nWährend sich die dunklen Winde bilden, kann das Ziel giftige Lachen verteilen." }
entries[210864] = { ["name"] = "Windende Schatten", ["text"] = "300 Meter Reichweite\nWirken in 1.3 sek. 4 sek. Abklingzeit\nDer Boss ruft Schattentornados hervor, die sich bei zufälligen Gegnern bilden. Nach 10 Sek. erscheinen die Tornados an den Gegnerpositionen, ziehen Ziele in der Nähe 4 Sek. lang zu sich heran und fügen ihnen so alle 1 Sek. 2134 Schattenschaden zu.\n\nWährend sich die dunklen Winde bilden, kann das Ziel giftige Lachen verteilen." }
